import collections
cnt = collections.Counter()
for cid, v in P.items():
    t = v['trigger']
    for k in ('changed_main','reserve_used','disputed'):
        if t[k]: cnt[k]+=1
    rec = dict(case_id=cid, prediction_text=v['prediction_text'], basis=v['basis'],
               confidence=v['confidence'], trigger=v['trigger'])
    assert set(rec)== {'case_id','prediction_text','basis','confidence','trigger'}
    assert 0.0 <= rec['confidence'] <= 1.0
